const items = $input.all();
const body = items[0].json.body || items[0].json;
const text = body.text || '';
const fromUser = body.user_id || '';
const fromName = body.user_name || '';

// Parse: @user reason
const match = text.match(/<@(\w+)(?:\|[^>]*)?>\s*(.*)/);
const toUser = match ? match[1] : '';
const reason = match ? match[2].trim() : text;

const emojis = [':tada:', ':star2:', ':trophy:', ':clap:', ':rocket:', ':heart:', ':fire:', ':100:'];
const randomEmoji = emojis[Math.floor(Math.random() * emojis.length)];

return [{json: {
  fromUser,
  fromName,
  toUser,
  reason: reason || 'Being awesome!',
  emoji: randomEmoji,
  timestamp: new Date().toISOString(),
  month: new Date().toISOString().slice(0, 7)
}}];

const items = $input.all();
const lastMonth = new Date();
lastMonth.setMonth(lastMonth.getMonth() - 1);
const monthKey = lastMonth.toISOString().slice(0, 7);

const monthlyKudos = items.filter(i => (i.json.month || '') === monthKey);
const counts = {};
for (const k of monthlyKudos) {
  const user = k.json.toUser || 'unknown';
  counts[user] = (counts[user] || 0) + 1;
}

const sorted = Object.entries(counts).sort((a, b) => b[1] - a[1]);
let summary = `:trophy: *Monthly Kudos Summary — ${monthKey}*\n\n`;
summary += `*Total kudos given:* ${monthlyKudos.length}\n\n`;
summary += '*Top recognized:*\n';
sorted.slice(0, 5).forEach(([user, count], i) => {
  const medal = i === 0 ? ':first_place_medal:' : i === 1 ? ':second_place_medal:' : i === 2 ? ':third_place_medal:' : ':star:';
  summary += `${medal} <@${user}> — ${count} kudos\n`;
});

return [{json: {summary, month: monthKey, totalKudos: monthlyKudos.length}}];
